using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Diagnostics;using System.Globalization;using System.Text;using System.Text.RegularExpressions;using System.Threading;using System.Windows.Forms;using Microsoft.Win32;using Gunt.ControlCenter.Models;
namespace Gunt.ControlCenter.Services {
 public sealed partial class DesktopService {
  public Action<ProcessStartInfo> LaunchOverride;
  public static string Quote(string value){if(value==null)return "\"\"";return "\""+Regex.Replace(Regex.Replace(value,@"(\\*)""","$1$1\\\""),@"(\\+)$","$1$1")+"\"";}
  void Launch(ProcessStartInfo info){if(LaunchOverride!=null)LaunchOverride(info);else using(var process=Process.Start(info)){}}
  public Dictionary<string,object> Optional(string name){string p=Path.Combine(Root,"config",name+".json");return File.Exists(p)?Read(name):new Dictionary<string,object>();}
  public static string S(Dictionary<string,object> d,string key,string fallback=""){object v;return d!=null&&d.TryGetValue(key,out v)&&v!=null?Convert.ToString(v,CultureInfo.InvariantCulture):fallback;}
  public static bool B(Dictionary<string,object> d,string key,bool fallback=false){object v;return d!=null&&d.TryGetValue(key,out v)&&v!=null?Convert.ToBoolean(v):fallback;}
  public static string Redact(string value){if(value==null)return "";string home=Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);if(!String.IsNullOrEmpty(home))value=Regex.Replace(value,Regex.Escape(home),"%USERPROFILE%",RegexOptions.IgnoreCase);value=Regex.Replace(value,@"(?i)(token|password|secret|api[_-]?key)\s*[:=]\s*[^\s]+","$1=[가림]");return Regex.Replace(value,@"\b(?:\d{1,3}\.){3}\d{1,3}\b","[IP 가림]");}
  public ProjectEntry[] Projects(){string p=Path.Combine(Root,"config","projects.json");if(!File.Exists(p))return new ProjectEntry[0];var store=Json.Deserialize<ProjectStore>(GuntConfiguration.ReadShared(p));if(store==null||(store.SchemaVersion!=1&&store.SchemaVersion!=2)||store.Projects==null)throw new InvalidDataException("프로젝트 설정 형식을 확인하세요. 원본은 덮어쓰지 않았습니다.");return store.Projects.OrderByDescending(x=>x.Pinned).ThenBy(x=>x.Order).ThenBy(x=>x.Name).ToArray();}
  public void ValidateProject(ProjectEntry p){if(p==null||String.IsNullOrWhiteSpace(p.Name)||p.Name.Length>80)throw new ArgumentException("프로젝트 이름은 1–80자로 입력하세요.");if(String.IsNullOrEmpty(p.Id)||!Regex.IsMatch(p.Id,@"^[a-zA-Z0-9_-]{1,80}$"))throw new ArgumentException("프로젝트 ID 형식이 올바르지 않습니다.");if(String.IsNullOrWhiteSpace(p.Directory)||p.Directory.IndexOfAny(new[]{'\r','\n','"'})>=0||!Path.IsPathRooted(p.Directory)||!Directory.Exists(p.Directory))throw new ArgumentException("실제로 존재하는 절대 경로를 선택하세요. 폴더를 자동 생성하지 않습니다.");if(!String.IsNullOrWhiteSpace(p.RepositoryUrl)&&!Regex.IsMatch(p.RepositoryUrl,@"^https://github\.com/[a-zA-Z0-9_.-]+/[a-zA-Z0-9_.-]+/?$"))throw new ArgumentException("GitHub 저장소 HTTPS 주소만 입력하세요. 인증·쿼리 정보는 저장하지 않습니다.");if(p.Commands!=null&&p.Commands.Any(c=>c==null||c.Length>2000||Regex.IsMatch(c,@"(?i)(token|password|secret|api[_-]?key)\s*=")))throw new ArgumentException("프로젝트 명령에 암호·토큰을 저장할 수 없습니다.");}
  void SaveProjects(IEnumerable<ProjectEntry> projects){var store=new ProjectStore{SchemaVersion=2,Projects=projects.ToList()};GuntConfiguration.Atomic(Root,Path.Combine(Root,"config","projects.json"),Json.Serialize(store),true);}
  public void SaveProject(ProjectEntry project){ValidateProject(project);ValidatePreferences(project.Developer);using(var m=new Mutex(false,"Local\\GUNTProjectsV25")){if(!m.WaitOne(10000))throw new IOException("다른 프로젝트 저장이 진행 중입니다.");try{var list=Projects().ToList();int at=list.FindIndex(x=>x.Id==project.Id);if(at<0)list.Add(project);else list[at]=project;SaveProjects(list);}finally{m.ReleaseMutex();}}}
  public void DeleteProject(string id){SaveProjects(Projects().Where(x=>x.Id!=id));}
  public void MoveProject(string id,int delta){var all=Projects().ToList();int at=all.FindIndex(x=>x.Id==id),next=at+delta;if(at<0||next<0||next>=all.Count||all[at].Pinned!=all[next].Pinned)return;var p=all[at];all[at]=all[next];all[next]=p;for(int i=0;i<all.Count;i++)all[i].Order=i;SaveProjects(all);}
  string AppPath(string key){var apps=Optional("apps");string exe=S(apps,key);if(String.IsNullOrEmpty(exe)||!File.Exists(exe))throw new FileNotFoundException("설치된 실행 파일을 확인할 수 없습니다: "+key);return exe;}
  public string LaunchProject(string id,string action){var p=Projects().FirstOrDefault(x=>x.Id==id);if(p==null)throw new ArgumentException("프로젝트를 찾지 못했습니다.");ValidateProject(p);ProcessStartInfo info;if(action=="folder")info=new ProcessStartInfo("explorer.exe",Quote(p.Directory)){UseShellExecute=true};else if(action=="ide")info=new ProcessStartInfo(AppPath("code"),Quote(p.Directory)){UseShellExecute=true};else if(action=="repository"){if(String.IsNullOrEmpty(p.RepositoryUrl))throw new ArgumentException("저장소 URL을 먼저 설정하세요.");info=new ProcessStartInfo(p.RepositoryUrl){UseShellExecute=true};}else if(action=="terminal")info=new ProcessStartInfo(AppPath("terminal"),"-w new -d "+Quote(p.Directory)+" --title "+Quote("GUnT_0x9 · "+p.Name)+" powershell.exe -NoExit"){UseShellExecute=true,WorkingDirectory=p.Directory};else if(action=="command"){if(p.Commands==null||p.Commands.Count==0)throw new ArgumentException("사용자가 설정한 명령이 없습니다.");string script="Set-Location -LiteralPath '"+p.Directory.Replace("'","''")+"'\r\n"+p.Commands[0];info=new ProcessStartInfo("powershell.exe","-NoExit -EncodedCommand "+Convert.ToBase64String(Encoding.Unicode.GetBytes(script))){UseShellExecute=true,WorkingDirectory=p.Directory};}else throw new ArgumentException("지원하지 않는 프로젝트 동작입니다.");Launch(info);var recent=State("project-recent");recent[p.Id]=DateTimeOffset.Now.ToString("o");GuntConfiguration.Atomic(Root,Path.Combine(Root,"state","project-recent.json"),Json.Serialize(recent),false);return "프로젝트 실행 요청: "+p.Name+" · "+action;}
  public ProfileEntry[] Profiles(){string folder=Path.Combine(Root,"config","profiles");if(!Directory.Exists(folder))return new ProfileEntry[0];return Directory.GetFiles(folder,"*.json").Select(path=>{var d=Json.Deserialize<Dictionary<string,object>>(GuntConfiguration.ReadShared(path));string id=Path.GetFileNameWithoutExtension(path);return new ProfileEntry{Id=id,Path=path,Name=S(d,"name",id),Builtin=B(d,"builtin")||new[]{"Developer","Daily","Gaming","Focus"}.Contains(id),Data=d};}).ToArray();}
  public Dictionary<string,object> Workspace(){return new Dictionary<string,object>{{"monitorVisible",MonitorVisible()},{"compact",B(Read("monitor"),"compact")},{"manualPaused",B(State("wallpaper-playback"),"ManualPaused")}};}
  [System.Runtime.InteropServices.DllImport("user32.dll")]static extern bool IsWindowVisible(IntPtr h);
  public bool MonitorVisible(){var h=GuntLayout.MonitorWindow();return h!=IntPtr.Zero&&IsWindowVisible(h);}
  public Dictionary<string,object> ProfileValues(ProfileEntry p){object compact=Get(p.Data,"settings.monitor.compact");return new Dictionary<string,object>{{"monitorVisible",B(p.Data,"monitorVisible")},{"compact",compact==null?B(p.Data,"compact"):Convert.ToBoolean(compact)},{"manualPaused",B(p.Data,"manualPaused")}};}
  public string ProfileState(){var active=State("profile-active");if(active.Count==0)return "사용자 설정 · 적용된 프로필 기록 없음";var p=Profiles().FirstOrDefault(x=>x.Id==S(active,"id")||x.Name==S(active,"name"));if(p==null)return S(active,"name","사용자 설정")+" · 저장 프로필 확인 필요";var current=Workspace();var expected=ProfileValues(p);bool match=expected.All(x=>Convert.ToString(current[x.Key])==Convert.ToString(x.Value));return p.Name+(match?" · 관리 설정 일치":" · 수동 변경 있음")+" (실제 재생은 Lively 정책 적용)";}
  public string ProfilePreview(ProfileEntry p){var current=Workspace();var values=ProfileValues(p);return String.Join("\n",new[]{"monitorVisible","compact","manualPaused"}.Select((key,i)=>new[]{"시스템 모니터 표시","간단한 모드","배경 수동 정지 정책"}[i]+": "+current[key]+" → "+values[key]))+"\n\n현재 배경 선택·저장된 모니터 위치·Windows 알림 설정은 바꾸지 않습니다.";}
  public string SaveWorkspaceProfile(string name){if(String.IsNullOrWhiteSpace(name)||name.Length>50)throw new ArgumentException("프로필 이름은 1–50자로 입력하세요.");string id="user-"+Guid.NewGuid().ToString("N").Substring(0,12);var data=Workspace();data["schemaVersion"]=2;data["name"]=name;data["builtin"]=false;data["restoreScope"]="workspace";GuntConfiguration.Atomic(Root,Path.Combine(Root,"config","profiles",id+".json"),Json.Serialize(data),true);return id;}
  public void RenameProfile(string id,string name){var p=Profiles().First(x=>x.Id==id);if(p.Builtin)throw new ArgumentException("기본 프로필은 이름을 바꾸지 않습니다.");if(String.IsNullOrWhiteSpace(name)||name.Length>50)throw new ArgumentException("프로필 이름을 확인하세요.");p.Data["name"]=name;GuntConfiguration.Atomic(Root,p.Path,Json.Serialize(p.Data),true);}
  public void DeleteProfile(string id){var p=Profiles().First(x=>x.Id==id);if(p.Builtin)throw new ArgumentException("기본 프로필은 삭제할 수 없습니다.");string folder=Path.Combine(Root,"backups","deleted-profiles",DateTime.Now.ToString("yyyyMMddHHmmssfff"));Directory.CreateDirectory(folder);File.Move(p.Path,Path.Combine(folder,Path.GetFileName(p.Path)));}
  public string SensorSummary(){var sample=State("sensors");DateTimeOffset stamp;if(!DateTimeOffset.TryParse(S(sample,"Timestamp"),out stamp)||DateTimeOffset.Now-stamp>TimeSpan.FromSeconds(12))return "최근 샘플 없음 · 공급자 갱신을 확인하세요.";string quality=S(sample,"TemperatureQuality");if(quality=="valid")return "실제 센서 연결 · "+S(sample,"TemperatureProvider")+" · "+stamp.ToLocalTime().ToString("HH:mm:ss");if(quality=="stale")return "오래된 값 · 공급자 갱신을 확인하세요.";if(quality=="mapping-required")return "장치 연결 필요 · 센서와 단위를 선택하세요.";return "센서 값 없음 · 공급자와 내보내기를 확인하세요.";}
  public HealthEntry[] Health(){var rows=new List<HealthEntry>();var runtime=Optional("runtime");foreach(var a in new[]{new[]{"bar","GUNT-Bar","상단 바","bar-reload"},new[]{"rainmeter","Rainmeter","Rainmeter","rainmeter-start"},new[]{"lively","Lively","Lively Wallpaper","wallpaper-settings"},new[]{"windhawk","windhawk","Windhawk","windhawk-open"},new[]{"flow","Flow.Launcher","Flow Launcher","flow-start"}}){try{var processes=Process.GetProcessesByName(a[1]);try{bool running=processes.Length>0;rows.Add(new HealthEntry{Id=a[0],Name=a[2],Status=running?(processes.All(x=>x.Responding)?"정상":"오류"):"중지",Detail=running?(processes.All(x=>x.Responding)?"실행 중 "+processes.Length+"개":"응답하지 않는 프로세스가 있습니다."):"프로세스를 찾지 못했습니다.",Action=a[3],ActionLabel=running?(a[0]=="bar"?"새로고침":"열기 / 확인"):"시작 / 확인"});}finally{foreach(var p in processes)p.Dispose();}}catch(Exception e){rows.Add(new HealthEntry{Id=a[0],Name=a[2],Status="확인 불가",Detail=e.Message});}}
   var liveRow=rows.FirstOrDefault(x=>x.Id=="lively");if(liveRow!=null&&liveRow.Status=="정상")liveRow.Detail+=" · "+CurrentWallpaperTitle()+" · "+(B(State("wallpaper-playback"),"ManualPaused")?"수동 중지 요청":"자동 정책");
   rows.Add(new HealthEntry{Id="monitor",Name="시스템 모니터",Status=MonitorVisible()?"정상":"중지",Detail=MonitorVisible()?"실제 Rainmeter 창 표시 중":"위젯이 숨겨져 있거나 창이 없습니다.",Action="monitor-toggle",ActionLabel="표시 / 숨김"});
   rows.Add(new HealthEntry{Id="profile",Name="작업공간",Status=State("profile-active").Count>0?"정상":"설정 필요",Detail=ProfileState()+" · 이전: "+S(State("profile-previous"),"name","기록 없음"),Action="page:profiles",ActionLabel="프로필"});
   using(var key=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run")){bool registered=key!=null&&!String.IsNullOrEmpty(Convert.ToString(key.GetValue("GUNTDesktop")));rows.Add(new HealthEntry{Id="startup",Name="로그인 복원",Status=registered?"정상":"설정 필요",Detail=registered?"시작 항목 등록됨 · 실제 재로그인 검증 별도":"GUNT 시작 등록 없음",Action="page:automation",ActionLabel="설정"});}
   string sensor=SensorSummary();rows.Add(new HealthEntry{Id="sensors",Name="하드웨어 센서",Status=sensor.StartsWith("실제")?"정상":"설정 필요",Detail=sensor,Action="page:sensors",ActionLabel="연결 확인"});
   foreach(var name in new[]{"theme","topbar","monitor","sensors","dock","startup"}){try{GuntConfiguration.Validate(name,Read(name));}catch(Exception e){rows.Add(new HealthEntry{Id="config-"+name,Name=name+" 설정",Status="오류",Detail=e.Message,Action="page:diagnostics",ActionLabel="진단"});}}
   var configErrors=rows.Where(x=>x.Id.StartsWith("config-")).ToArray();rows.Add(new HealthEntry{Id="config",Name="설정 무결성",Status=configErrors.Length==0?"정상":"오류",Detail=configErrors.Length==0?"6개 설정의 범위·형식 검사 통과":String.Join("; ",configErrors.Select(x=>x.Name+": "+x.Detail)),Action="page:diagnostics",ActionLabel="진단"});
   try{var layout=GuntLayout.Resolve(Root,0);rows.Add(new HealthEntry{Id="layout",Name="모니터 배치",Status=Convert.ToBoolean(layout["temporaryFallback"])?"설정 필요":"정상",Detail=Screen.AllScreens.Length+"개 화면 · "+(Convert.ToBoolean(layout["temporaryFallback"])?"저장된 화면이 없어 주 화면에 임시 배치":"저장 배치 해석 가능"),Action="page:displays",ActionLabel="배치 확인"});}catch(Exception e){rows.Add(new HealthEntry{Id="layout",Name="모니터 배치",Status="확인 불가",Detail=e.Message});}
   return rows.ToArray();}
  public string Recover(string action){var runtime=Optional("runtime");if(action=="bar-reload"&&Process.GetProcessesByName("GUNT-Bar").Length==0){string bar=Path.Combine(Root,"bin","GUNT-Bar.exe");if(!File.Exists(bar))throw new FileNotFoundException("상단 바 빌드 파일이 없습니다.");Launch(new ProcessStartInfo(bar,Quote(Root)){UseShellExecute=true});return "프로젝트 상단 바 실행을 요청했습니다.";}if(action=="rainmeter-start"||action=="flow-start"){string key=action=="rainmeter-start"?"rainmeter":"flow",name=action=="rainmeter-start"?"Rainmeter":"Flow.Launcher";if(Process.GetProcessesByName(name).Length>0)return name+"는 이미 실행 중입니다.";string exe=S(runtime,key);if(!File.Exists(exe))throw new FileNotFoundException(name+" 경로 설정이 필요합니다.");Launch(new ProcessStartInfo(exe){UseShellExecute=true});return name+" 실행을 요청했습니다.";}if(action=="windhawk-open"){string exe=S(runtime,"windhawk");if(!File.Exists(exe))throw new FileNotFoundException("Windhawk 경로를 확인하세요.");Open(exe);return "Windhawk 설정 창을 요청했습니다.";}Action(action);return "구성 요소 요청 완료: "+action;}
  public string[] ConfigurationSnapshots(){string folder=Path.Combine(Root,"backups","settings-v24");var names=new[]{"theme","topbar","monitor","sensors","dock","startup","ux"};return Directory.Exists(folder)?Directory.GetFiles(folder,"*.json",SearchOption.AllDirectories).Where(x=>names.Contains(Path.GetFileNameWithoutExtension(x))).OrderByDescending(File.GetLastWriteTimeUtc).Take(40).ToArray():new string[0];}
  public string SnapshotPreview(string path){if(!ConfigurationSnapshots().Contains(path,StringComparer.OrdinalIgnoreCase))throw new ArgumentException("선택한 백업을 다시 확인하세요.");string name=Path.GetFileNameWithoutExtension(path);var old=Json.Deserialize<Dictionary<string,object>>(GuntConfiguration.ReadShared(path));var current=Read(name);return String.Join("\n",old.Where(pair=>Json.Serialize(Get(current,pair.Key))!=Json.Serialize(pair.Value)).Select(pair=>pair.Key+": "+Json.Serialize(Get(current,pair.Key))+" → "+Json.Serialize(pair.Value)));}
  public string RestoreConfigurationSnapshot(string path){if(!ConfigurationSnapshots().Contains(path,StringComparer.OrdinalIgnoreCase))throw new ArgumentException("목록에서 확인한 설정 백업만 복원합니다.");string config=Path.GetFileNameWithoutExtension(path);var previous=Json.Deserialize<Dictionary<string,object>>(GuntConfiguration.ReadShared(path));GuntConfiguration.Validate(config,previous);var current=Read(config);var fields=previous.Select(pair=>new SettingField{Config=config,Key=pair.Key,Kind="object",Label=config+"."+pair.Key,Original=Json.Serialize(Get(current,pair.Key)),Value=pair.Value}).ToArray();return "설정 스냅샷 복원: "+config+" · "+Apply(fields);}
  public string DiagnosticReport(){var lines=Health().Select(x=>x.Name+" | "+x.Status+" | "+Redact(x.Detail)).ToList();lines.Insert(0,"GUnT_0x9 Desktop 진단 · "+DateTimeOffset.Now.ToString("o"));foreach(var screen in Screen.AllScreens)lines.Add(screen.DeviceName+" · "+screen.Bounds.Width+"×"+screen.Bounds.Height+" · "+GuntLayout.Scale(screen)*100+"%");lines.Add("File Explorer Styler: 기존 XAML 충돌 때문에 비활성 유지 권장. 실제 상태는 Windhawk 페이지에서 확인.");return String.Join(Environment.NewLine,lines);}
 }
